CREATE TABLE business_identifier_definitions (
    id UUID NOT NULL CONSTRAINT business_identifier_definitions_pkey PRIMARY KEY,
    tenant_id UUID NOT NULL CONSTRAINT fk_business_identifier_definition_tenant REFERENCES tenants (id),
    identifier_key VARCHAR(64) NOT NULL,
    label VARCHAR(128) NOT NULL,
    required_flag BOOLEAN DEFAULT FALSE NOT NULL,
    primary_flag BOOLEAN DEFAULT FALSE NOT NULL,
    searchable_flag BOOLEAN DEFAULT TRUE NOT NULL,
    extractable_flag BOOLEAN DEFAULT FALSE NOT NULL,
    displayable_flag BOOLEAN DEFAULT TRUE NOT NULL,
    display_order INT DEFAULT 0 NOT NULL,
    active_flag BOOLEAN DEFAULT TRUE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    validation_type VARCHAR(32) DEFAULT 'TEXT' NOT NULL,
    exact_length INT,
    min_length INT,
    max_length INT,
    case_normalization VARCHAR(16) DEFAULT 'UPPER' NOT NULL,
    strip_separators_flag BOOLEAN DEFAULT FALSE NOT NULL,
    allowed_values TEXT,
    custom_pattern VARCHAR(512),
    CONSTRAINT uq_business_identifier_definition_key UNIQUE (tenant_id, identifier_key)
);
CREATE INDEX idx_business_identifier_definitions_tenant_order
    ON business_identifier_definitions (tenant_id, display_order);
CREATE UNIQUE INDEX uq_business_identifier_one_active_primary
    ON business_identifier_definitions (tenant_id) WHERE primary_flag = TRUE AND active_flag = TRUE;
CREATE TABLE business_records (
    id UUID NOT NULL CONSTRAINT business_records_pkey PRIMARY KEY,
    tenant_id UUID NOT NULL CONSTRAINT fk_business_records_tenant REFERENCES tenants (id),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    version BIGINT DEFAULT 0 NOT NULL
);
CREATE INDEX idx_business_records_tenant ON business_records (tenant_id);
CREATE TABLE business_record_identifiers (
    id UUID NOT NULL CONSTRAINT business_record_identifiers_pkey PRIMARY KEY,
    tenant_id UUID NOT NULL CONSTRAINT fk_business_record_identifier_tenant REFERENCES tenants (id),
    business_record_id UUID NOT NULL CONSTRAINT fk_business_record_identifier_record
        REFERENCES business_records (id),
    definition_id UUID NOT NULL CONSTRAINT fk_business_record_identifier_definition
        REFERENCES business_identifier_definitions (id),
    identifier_value VARCHAR(512) NOT NULL,
    normalized_value VARCHAR(512) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uq_business_record_definition UNIQUE (business_record_id, definition_id)
);
CREATE INDEX idx_business_record_identifiers_record ON business_record_identifiers (business_record_id);
CREATE INDEX idx_business_record_identifiers_tenant_record
    ON business_record_identifiers (tenant_id, business_record_id);
CREATE INDEX idx_business_identifier_lookup
    ON business_record_identifiers (tenant_id, definition_id, normalized_value);

CREATE OR REPLACE FUNCTION enforce_primary_business_identifier_unique()
RETURNS trigger AS $$
DECLARE
    is_active_primary BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM business_identifier_definitions d
         WHERE d.id = NEW.definition_id AND d.tenant_id = NEW.tenant_id
           AND d.primary_flag = TRUE AND d.active_flag = TRUE
    ) INTO is_active_primary;
    IF is_active_primary THEN
        PERFORM pg_advisory_xact_lock(hashtext(NEW.tenant_id::text || ':' || NEW.definition_id::text),
            hashtext(NEW.normalized_value));
        IF EXISTS (
            SELECT 1 FROM business_record_identifiers bri
             WHERE bri.tenant_id = NEW.tenant_id AND bri.definition_id = NEW.definition_id
               AND bri.normalized_value = NEW.normalized_value AND bri.id <> NEW.id
        ) THEN
            RAISE EXCEPTION 'Duplicate primary business identifier value for tenant'
                USING ERRCODE = '23505', CONSTRAINT = 'uq_business_primary_identifier_value';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_business_identifier_primary_unique
    BEFORE INSERT OR UPDATE OF tenant_id, definition_id, normalized_value ON business_record_identifiers
    FOR EACH ROW EXECUTE FUNCTION enforce_primary_business_identifier_unique();

CREATE OR REPLACE FUNCTION validate_primary_business_identifier_definition()
RETURNS trigger AS $$
BEGIN
    IF NEW.primary_flag = TRUE AND NEW.active_flag = TRUE AND EXISTS (
        SELECT 1 FROM business_record_identifiers bri
         WHERE bri.tenant_id = NEW.tenant_id AND bri.definition_id = NEW.id
         GROUP BY bri.normalized_value HAVING COUNT(*) > 1
    ) THEN
        RAISE EXCEPTION 'Identifier definition cannot become Primary because existing values are not unique'
            USING ERRCODE = '23505', CONSTRAINT = 'uq_business_primary_identifier_value';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_business_identifier_definition_primary_unique
    BEFORE INSERT OR UPDATE OF primary_flag, active_flag ON business_identifier_definitions
    FOR EACH ROW EXECUTE FUNCTION validate_primary_business_identifier_definition();
